<?php
function rwReady():bool{try{q('SELECT id FROM research_milestones LIMIT 1');return true;}catch(Throwable $e){return false;}}
function rwRequire(bool $ok,string $msg):void{if(!$ok)throw new RuntimeException($msg);}
function rwPL(array $u,array $r):bool{return !empty($u['active'])&&$u['role']==='pl'&&$u['department']===$r['department'];}
function rwEvaluator(array $u,array $r):bool{return rwReady()&&(bool)one('SELECT user_id FROM research_evaluators WHERE project_id=? AND user_id=?',[$r['id'],$u['id']]);}
function rwAudit(array $u,int $id,string $kind,array $details):void{q('INSERT INTO research_updates(project_id,actor_id,kind,details,created_at) VALUES(?,?,?,?,?)',[$id,$u['id'],$kind,json_encode($details,JSON_THROW_ON_ERROR),now()]);}
function rwRecipients(array $r):array{$ids=[$r['student_id'],$r['supervisor_id']];foreach(all("SELECT id FROM users WHERE active=1 AND (role='daa' OR (role='pl' AND department=?))",[$r['department']])as $x)$ids[]=$x['id'];return array_unique($ids);}
function rwNotify(array $r,string $event,string $body,array $ids):void{global $config;foreach(array_unique($ids)as $id){$u=one('SELECT email FROM users WHERE id=? AND active=1',[$id]);if($u)q('INSERT INTO outbox(recipient,subject,body,created_at) VALUES(?,?,?,?)',[$u['email'],'Research #'.$r['id'].' — '.$event,$body."\n\nOpen your research workspace (sign in or request an email verification code):\n".rtrim($config['url'],'/').'/?page=rw_access&project='.$r['id'],now()]);}}
function rwProgrammes():array{return array_values(array_filter(examProgrammes(),fn($p)=>str_starts_with($p,'BSc.')));}
function rwAuthPost(array $p):void{
 rwRequire(rwReady(),'Research workflow setup is required.');$action=$p['action'];
 if($action==='rw_code'){
  $email=strtolower(trim($p['email']??''));rwRequire(filter_var($email,FILTER_VALIDATE_EMAIL)!==false,'Enter a valid email address.');$register=($p['register']??'')==='1';$data=[];
  if($register){rwRequire((bool)preg_match('/^[a-z0-9._%+\-]+\.cnr@rub\.edu\.bt$/iD',$email),'Use your student email ending in .cnr@rub.edu.bt.');foreach(['name'=>160,'student_number'=>60,'department'=>160,'programme'=>160,'title'=>190,'scope'=>10000]as $k=>$n)$data[$k]=researchText($p,$k,$n);rwRequire(in_array($data['programme'],rwProgrammes(),true)&&examProgrammeDepartment($data['programme'])===$data['department'],'Choose a programme in your department.');rwRequire(($p['final_year']??'')==='1','Confirm that you are a final-year student.');$data['supervisor_id']=(int)($p['supervisor_id']??0);$data['period_id']=(int)($p['period_id']??0);rwCheckRegistration($data);}
  $identity=hash('sha256','rw|'.$email);$ip=hash('sha256','rw-ip|'.($_SERVER['REMOTE_ADDR']??''));foreach([$identity,$ip]as $key){rwRequire((int)q('SELECT COUNT(*) FROM login_attempts WHERE identity=? AND attempted_at>?',[$key,time()-900])->fetchColumn()<5,'Too many code requests. Try again in 15 minutes.');q('INSERT INTO login_attempts(identity,attempted_at) VALUES(?,?)',[$key,time()]);}
  $u=one('SELECT * FROM users WHERE email=?',[$email]);if(!$register)rwRequire($u&&$u['active']&&researchAccess($u),'Your email is not registered for research access. Please contact the ICT Section.');else rwRequire(!$u||($u['active']&&$u['role']==='student'),'This email is already assigned to another or inactive account. Contact ICT.');
  $code=(string)random_int(100000,999999);$_SESSION['rw_auth']=['email'=>$email,'hash'=>password_hash($code,PASSWORD_DEFAULT),'expires'=>time()+600,'tries'=>0,'register'=>$register,'data'=>$data,'project'=>(int)($p['project']??0)];q('INSERT INTO outbox(recipient,subject,body,created_at) VALUES(?,?,?,?)',[$email,'CNR Research — email verification code',"Your verification code is $code. It expires in 10 minutes. Do not share it. If you did not request access, ignore this message.",now()]);return;
 }
 rwRequire($action==='rw_verify','Unknown access action.');$a=$_SESSION['rw_auth']??[];rwRequire($a&&$a['expires']>=time()&&$a['tries']<5,'Verification expired. Request a new code.');$_SESSION['rw_auth']['tries']++;rwRequire(preg_match('/^[0-9]{6}$/D',$p['code']??'')&&password_verify($p['code'],$a['hash']),'Incorrect verification code.');
 db()->beginTransaction();try{$u=one('SELECT * FROM users WHERE email=?',[$a['email']]);$project=$a['project'];if($a['register']){$d=$a['data'];rwCheckRegistration($d);rwRequire(!$u||($u['active']&&$u['role']==='student'),'Account not available. Contact ICT.');if(!$u){q("INSERT INTO users(name,email,password,role,department) VALUES(?,?,?,'student',?)",[$d['name'],$a['email'],password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),$d['department']]);$u=one('SELECT * FROM users WHERE id=?',[(int)db()->lastInsertId()]);}else rwRequire($u['department']===$d['department'],'Existing department differs. Contact ICT to update your account.');$s=one('SELECT * FROM research_students WHERE user_id=?',[$u['id']]);if($s)rwRequire($s['student_number']===$d['student_number']&&$s['programme']===$d['programme'],'Existing student details differ. Contact ICT.');else q('INSERT INTO research_students(user_id,student_number,programme) VALUES(?,?,?)',[$u['id'],$d['student_number'],$d['programme']]);
 rwRequire(!one('SELECT id FROM research_projects WHERE student_id=? AND period_id=?',[$u['id'],$d['period_id']]),'You already registered for this period. Use staff/student email access to open your project.');q("INSERT INTO research_projects(student_id,supervisor_id,period_id,department,title,objectives,methodology,team,outcomes,funding,status,created_at,updated_at) VALUES(?,?,?,?,?,?,'','','',0,'Submitted',?,?)",[$u['id'],$d['supervisor_id'],$d['period_id'],$d['department'],$d['title'],$d['scope'],now(),now()]);$project=(int)db()->lastInsertId();$r=one('SELECT * FROM research_projects WHERE id=?',[$project]);rwAudit($u,$project,'Registration submitted',$d);rwNotify($r,'Registration received','Your research registration has been submitted. Your supervisor will review it and you will receive an email when a decision is made.',[$u['id']]);rwNotify($r,'Supervision request',$d['name'].' ('.$d['student_number'].') from '.$d['department'].' / '.$d['programme'].' has requested your supervision for: '.$d['title']."\n\nWorking topic statement: ".$d['scope']."\nPlease review the request in your workspace.",[$d['supervisor_id']]);
 }else rwRequire($u&&$u['active']&&researchAccess($u),'Account access is no longer available.');db()->commit();session_regenerate_id(true);unset($_SESSION['rw_auth']);$_SESSION['user']=$u['id'];$_SESSION['password_version']=hash('sha256',$u['password']);$_SESSION['rw_destination']=$project;
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function rwCheckRegistration(array $d):void{$p=one('SELECT * FROM research_periods WHERE id=?',[$d['period_id']]);$today=date('Y-m-d');rwRequire($p&&$p['active']&&$p['department']===$d['department']&&$p['opens_on']<=$today&&$p['closes_on']>=$today,'Choose an open registration period for your department.');rwRequire((bool)one("SELECT id FROM users WHERE id=? AND active=1 AND department=? AND role IN ('faculty','hod','pl','daa')",[$d['supervisor_id'],$d['department']]),'Choose an active supervisor in your department.');}
function rwMilestones(array $r):array{return all('SELECT * FROM research_milestones WHERE period_id=? ORDER BY sequence_no',[$r['period_id']]);}
function rwStatus(array $r,array $m):array{$w=one("SELECT kind FROM research_work WHERE project_id=? AND milestone_id=? AND kind<>'Comment' ORDER BY id DESC",[$r['id'],$m['id']]);$k=$w['kind']??'';if($k==='Completed')return ['Completed','done'];if(in_array($k,['Submission','Resubmission','Returned feedback'],true))return [$k==='Returned feedback'?'Changes requested':'Awaiting review','review'];if($m['due_date']<date('Y-m-d'))return ['Overdue','late'];if($m['due_date']<=date('Y-m-d',strtotime('+7 days')))return ['Due soon','soon'];return ['Upcoming','future'];}
function rwSaveFile():array{$f=$_FILES['document']??[];if(($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return ['',''];rwRequire(($f['error']??1)===UPLOAD_ERR_OK&&$f['size']>0&&$f['size']<=20*1024*1024&&is_uploaded_file($f['tmp_name']),'Upload a DOCX or PDF up to 20 MB.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));rwRequire(in_array($ext,['docx','pdf'],true),'Only DOCX or PDF documents are allowed.');if($ext==='pdf')rwRequire(str_starts_with(file_get_contents($f['tmp_name'],false,null,0,5),'%PDF-'),'Invalid PDF.');else{$z=new ZipArchive();rwRequire($z->open($f['tmp_name'])===true,'Invalid DOCX.');$valid=$z->locateName('word/document.xml')!==false;$z->close();rwRequire($valid,'Invalid DOCX.');}$dir=__DIR__.'/../../storage/research-documents';if(!is_dir($dir))mkdir($dir,0700,true);$key=bin2hex(random_bytes(24)).'.'.$ext;rwRequire(move_uploaded_file($f['tmp_name'],$dir.'/'.$key),'Document could not be saved.');chmod($dir.'/'.$key,0600);return [$key,mb_substr(basename($f['name']),0,240)];}
function rwPost(array $u,array $p):int{
 rwRequire(rwReady()&&researchAccess($u),'Research access required.');$action=$p['action'];$id=(int)($p['id']??0);$file='';db()->beginTransaction();try{
 if($action==='rw_timeline') {rwRequire(researchManager($u),'DAA or Admin access required.');$pid=(int)($p['period_id']??0);rwRequire((bool)one('SELECT id FROM research_periods WHERE id=?',[$pid]),'Select a registration period.');$data=rwReadTimeline($p);$old=all('SELECT * FROM research_milestones WHERE period_id=?',[$pid]);foreach($data as $row){$existing=one('SELECT id FROM research_milestones WHERE period_id=? AND sequence_no=?',[$pid,$row[0]]);if($existing)q('UPDATE research_milestones SET title=?,start_date=?,due_date=?,student_action=?,supervisor_action=?,coordinator_action=?,phase=?,evaluator_visible=? WHERE id=?',[...array_slice($row,1),$existing['id']]);else q('INSERT INTO research_milestones(period_id,sequence_no,title,start_date,due_date,student_action,supervisor_action,coordinator_action,phase,evaluator_visible) VALUES(?,?,?,?,?,?,?,?,?,?)',[$pid,...$row]);}rwAudit($u,0,'Timeline published',['period'=>$pid,'before'=>$old,'after'=>$data]);$id=0;
 }else{$r=researchGet($u,$id);$manager=researchManager($u);$pl=rwPL($u,$r);$owner=(int)$r['student_id']===(int)$u['id'];$supervisor=(int)$r['supervisor_id']===(int)$u['id'];$eval=rwEvaluator($u,$r);rwRequire((int)($p['revision']??0)===(int)$r['revision'],'Project changed. Refresh before saving.');$comments=researchText($p,'comments');
 if($action==='rw_assign'){rwRequire($manager||$pl,'PL, DAA or Admin access required.');$target=one("SELECT * FROM users WHERE id=? AND active=1 AND role IN ('faculty','hod','pl','daa')",[(int)($p['teacher_id']??0)]);rwRequire((bool)$target,'Choose active teaching staff.');if(($p['assignment']??'')==='evaluator'){rwRequire($manager,'DAA or Admin assigns evaluators.');rwRequire(!one('SELECT user_id FROM research_evaluators WHERE project_id=? AND user_id=?',[$id,$target['id']]),'Evaluator already assigned.');$shared=one("SELECT * FROM research_work WHERE id=? AND project_id=? AND file_key<>''",[(int)($p['document_id']??0),$id]);rwRequire((bool)$shared,'Select a submitted document to share with the evaluator.');$milestone=one('SELECT id FROM research_milestones WHERE period_id=? AND evaluator_visible=1 ORDER BY sequence_no',[$r['period_id']]);rwRequire((bool)$milestone,'Publish the evaluation milestones first.');q('INSERT INTO research_evaluators(project_id,user_id,assigned_by,assigned_at) VALUES(?,?,?,?)',[$id,$target['id'],$u['id'],now()]);q('INSERT INTO research_work(project_id,milestone_id,actor_id,kind,comments,file_key,file_name,created_at) VALUES(?,?,?,?,?,?,?,?)',[$id,$milestone['id'],$u['id'],'Submission','Shared with evaluator '.$target['name'].': '.$comments,$shared['file_key'],$shared['file_name'],now()]);$event='Evaluator assigned';}else{rwRequire($target['department']===$r['department'],'Select a supervisor from this department.');q("UPDATE research_projects SET supervisor_id=?,status='Submitted' WHERE id=?",[$target['id'],$id]);$event='Supervisor reassigned';}rwAudit($u,$id,$event,['comments'=>$comments,'teacher'=>$target['id'],'previous_supervisor'=>$r['supervisor_id']]);rwNotify($r,$event,$comments,array_merge(rwRecipients($r),[$target['id']]));
 }elseif($action==='rw_grade'){rwRequire($supervisor||$manager,'Only supervisor, DAA or Admin can enter grades.');foreach(['secured','maximum','weighting']as $k)rwRequire(is_numeric($p[$k]??null)&&is_finite((float)$p[$k]),'Enter valid numeric marks and weighting.');$a=(float)$p['secured'];$b=(float)$p['maximum'];$w=(float)$p['weighting'];rwRequire($a>=0&&$b>0&&$b<=100000&&$a<=$b&&$w>0&&$w<=100,'Check secured marks, maximum and weighting (0–100%).');$actor=(int)$r['supervisor_id'];$before=one('SELECT * FROM research_grades WHERE project_id=? AND actor_id=?',[$id,$actor]);if($before)q('UPDATE research_grades SET secured=?,maximum=?,weighting=?,comments=?,updated_at=? WHERE project_id=? AND actor_id=?',[$a,$b,$w,$comments,now(),$id,$actor]);else q('INSERT INTO research_grades(project_id,actor_id,secured,maximum,weighting,comments,updated_at) VALUES(?,?,?,?,?,?,?)',[$id,$actor,$a,$b,$w,$comments,now()]);rwAudit($u,$id,'Grade submitted',['before'=>$before,'secured'=>$a,'maximum'=>$b,'weighting'=>$w,'comments'=>$comments]);rwNotify($r,'Grade submitted','The supervisor has submitted research marks for review.',array_diff(rwRecipients($r),[$r['student_id']]));
 }elseif($action==='rw_work'){$m=one('SELECT * FROM research_milestones WHERE id=? AND period_id=?',[(int)($p['milestone_id']??0),$r['period_id']]);rwRequire((bool)$m,'Choose a milestone from this project timeline.');$kind=$p['kind']??'';rwRequire(in_array($kind,['Submission','Resubmission','Returned feedback','Completed','Comment'],true),'Choose a valid action.');if(!$manager&&!$pl&&!$owner&&!$supervisor)rwRequire($eval&&(bool)$m['evaluator_visible'],'Evaluator access is limited to the assigned evaluation milestones.');if(in_array($kind,['Submission','Resubmission'],true))rwRequire($owner&&in_array($r['status'],['Approved','Completed'],true),'Student submissions require supervisor acceptance.');if($kind==='Returned feedback')rwRequire($manager||$supervisor||($eval&&$m['evaluator_visible']),'Reviewer access required.');if($kind==='Completed')rwRequire($manager||$supervisor,'Supervisor or DAA confirms milestone completion.');[$file,$name]=rwSaveFile();if(in_array($kind,['Submission','Resubmission'],true))rwRequire($file!=='','Attach your research document.');q('INSERT INTO research_work(project_id,milestone_id,actor_id,kind,comments,file_key,file_name,created_at) VALUES(?,?,?,?,?,?,?,?)',[$id,$m['id'],$u['id'],$kind,$comments,$file,$name,now()]);$recipients=rwRecipients($r);if($m['evaluator_visible'])$recipients=array_merge($recipients,array_column(all('SELECT user_id FROM research_evaluators WHERE project_id=?',[$id]),'user_id'));rwNotify($r,$kind.' — '.$m['title'],$u['name'].': '.$comments,$recipients);
 }else throw new RuntimeException('Unknown research workflow action.');$changed=q('UPDATE research_projects SET revision=revision+1,updated_at=? WHERE id=? AND revision=?',[now(),$id,$r['revision']]);rwRequire($changed->rowCount()===1,'Project changed. Refresh before saving.');}
 db()->commit();return $id;
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();if($file)unlink(__DIR__.'/../../storage/research-documents/'.$file);throw $e;}
}
function rwDownload(array $u):never{$w=one('SELECT * FROM research_work WHERE id=?',[(int)($_GET['file']??0)]);rwRequire((bool)$w,'Document unavailable.');$r=researchGet($u,(int)$w['project_id']);$full=researchManager($u)||rwPL($u,$r)||(int)$r['student_id']===(int)$u['id']||(int)$r['supervisor_id']===(int)$u['id'];if(!$full){$m=one('SELECT evaluator_visible FROM research_milestones WHERE id=?',[$w['milestone_id']]);rwRequire(rwEvaluator($u,$r)&&!empty($m['evaluator_visible']),'Document is not shared with this evaluator.');}rwRequire(preg_match('/^[a-f0-9]{48}\.(pdf|docx)$/D',$w['file_key'])===1,'Document unavailable.');$path=__DIR__.'/../../storage/research-documents/'.$w['file_key'];rwRequire(is_file($path),'Document unavailable.');header('Content-Type: application/octet-stream');header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($w['file_name']));readfile($path);exit;}
